use ark_bls12_381::Bls12_381;
use ark_groth16::{checked::{check,check_profiled_with_progress}, prepare_verifying_key, Groth16, ProvingKey, VerifyingKey};
use ark_serialize::{CanonicalDeserialize,CanonicalSerialize};
use ark_std::rand::rngs::OsRng;
use plan_a_joint_circuit::fixture::{fixed, public_inputs};
use sha2::{Digest,Sha256};
use serde_json::json;
use std::{env,fs,io::{self,Cursor,Write},path::{Path,PathBuf},time::Instant};
fn write<T:CanonicalSerialize>(p:&Path,x:&T){let mut b=Vec::new();x.serialize_compressed(&mut b).unwrap();fs::write(p,b).unwrap();}
fn read(p:&Path)->Vec<u8>{fs::read(p).unwrap()}
fn sha(b:&[u8])->String{hex::encode(Sha256::digest(b))}
fn decode_exact<T:CanonicalDeserialize+CanonicalSerialize>(b:&[u8])->T{let mut c=Cursor::new(b);let x=T::deserialize_compressed(&mut c).unwrap();assert_eq!(c.position() as usize,b.len());let mut out=Vec::new();x.serialize_compressed(&mut out).unwrap();assert_eq!(out,b);x}
fn setup(d:&Path){assert!(!d.exists());fs::create_dir_all(d).unwrap();let t=Instant::now();let(pk,m,sm)=Groth16::<Bls12_381>::generate_random_parameters_with_reduction_and_material_profiled(fixed::<3>(3,0,20,20,32),&mut OsRng).unwrap();let setup_ns=t.elapsed().as_nanos();let t=Instant::now();write(&d.join("pk.bin"),&pk);write(&d.join("vk.bin"),&pk.vk);write(&d.join("checking.bin"),&m);let serialization_write_ns=t.elapsed().as_nanos();let(pb,vb,mb)=(read(&d.join("pk.bin")),read(&d.join("vk.bin")),read(&d.join("checking.bin")));println!("{}",json!({"event":"setup","setup_ns":setup_ns,"combined_generator_ns":sm.total_ns,"power_construction_ns":sm.power_construction_ns,"serialization_write_ns":serialization_write_ns,"ordinary_setup_excluding_posthoc_power_loop_ns":sm.total_ns-sm.power_construction_ns,"constraints":m.num_constraints,"instances":m.num_instance_variables,"witnesses":m.num_witness_variables,"domain":m.domain_size,"bytes":{"pk":pb.len(),"vk":vb.len(),"material":mb.len()},"pk_sha256":sha(&pb),"vk_sha256":sha(&vb),"material_sha256":sha(&mb)}));}
fn gate(d:&Path){let full=Instant::now();let t=Instant::now();let(pb,vb,mb)=(read(&d.join("pk.bin")),read(&d.join("vk.bin")),read(&d.join("checking.bin")));let file_read_ns=t.elapsed().as_nanos();println!("{}",json!({"event":"stage","stage":"file_read","duration_ns":file_read_ns}));io::stdout().flush().unwrap();let shape=fixed::<3>(3,0,20,20,32);let t=Instant::now();let(checked,m)=check_profiled_with_progress::<Bls12_381,_>(&pb,&vb,&mb,shape,|stage,duration_ns|{println!("{}",json!({"event":"stage","stage":stage,"duration_ns":duration_ns}));io::stdout().flush().unwrap();}).unwrap();let checker_call_ns=t.elapsed().as_nanos();let full_load_ns=full.elapsed().as_nanos();let c=fixed::<3>(2,7,20,20,32);let inputs=public_inputs(&c);let t=Instant::now();let proof=checked.prove(c,&mut OsRng).unwrap();let prove_ns=t.elapsed().as_nanos();let t=Instant::now();let verified=Groth16::<Bls12_381>::verify_proof(checked.prepared_vk(),&proof,&inputs).unwrap();let verify_ns=t.elapsed().as_nanos();assert!(verified);let mut bad=pb.clone();bad[0]^=0xff;assert!(check::<Bls12_381,_>(&bad,&vb,&mb,fixed::<3>(3,0,20,20,32)).is_err());println!("{}",json!({"event":"gate","relation":"randomized-dummy-joint","file_read_ns":file_read_ns,"checker_call_ns":checker_call_ns,"full_load_ns":full_load_ns,"shape_template_constructed_before_checker_call":true,"metrics":{"pk_decode_ns":m.pk_decode_ns,"vk_decode_ns":m.vk_decode_ns,"material_decode_ns":m.material_decode_ns,"relation_ns":m.relation_ns,"powers_ns":m.powers_ns,"reconstruction_ns":m.reconstruction_ns,"direct_query_ns":m.direct_query_ns,"b_cross_ns":m.b_cross_ns,"equation_ns":m.equation_ns,"binding_ns":m.binding_ns,"checker_total_ns":m.total_ns},"bytes":{"pk":pb.len(),"vk":vb.len(),"material":mb.len()},"prove_ns":prove_ns,"verify_ns":verify_ns,"verified":verified,"failed_bundle_rejected":true,"receipt":hex::encode(checked.receipt())}));}
fn ordinary(d:&Path){let full=Instant::now();let t=Instant::now();let(pb,vb)=(read(&d.join("pk.bin")),read(&d.join("vk.bin")));let file_read_ns=t.elapsed().as_nanos();let t=Instant::now();let pk:ProvingKey<Bls12_381>=decode_exact(&pb);let pk_decode_ns=t.elapsed().as_nanos();let t=Instant::now();let vk:VerifyingKey<Bls12_381>=decode_exact(&vb);let vk_decode_ns=t.elapsed().as_nanos();assert_eq!(pk.vk,vk);let t=Instant::now();let _prepared=prepare_verifying_key(&vk);let prepare_vk_ns=t.elapsed().as_nanos();println!("{}",json!({"event":"ordinary_load","relation":"randomized-dummy-joint","file_read_ns":file_read_ns,"pk_decode_ns":pk_decode_ns,"vk_decode_ns":vk_decode_ns,"prepare_vk_ns":prepare_vk_ns,"full_load_ns":full.elapsed().as_nanos(),"canonical_exact":true,"embedded_vk_equal":true,"bytes":{"pk":pb.len(),"vk":vb.len()}}));}
fn main(){let a=env::args().collect::<Vec<_>>();let d=PathBuf::from(&a[2]);match a[1].as_str(){"setup"=>setup(&d),"gate"=>gate(&d),"ordinary"=>ordinary(&d),_=>panic!("setup|gate|ordinary DIR")}}
